/**
 * 人生之书的纯 JS 引擎（schema 2）。
 *
 * 和 @ohos/dsh-sanguo 是同一条分工：引擎是裁判，模型只是叙述者。
 * 引擎只做四件事——把一章的选项结算成六个数值、记住你走过的路（flags/tags）、
 * 让重复的欲望产生复利、在最后一页按「主题 × 代价」给出三十种结局之一。
 * 它不生成任何叙述文本。
 *
 * schema 2 的三个新规则：
 *   1. 选项可以带 requires：前置选择没有发生，这条路就不存在（锁住并给出原因）。
 *   2. 同一欲望每选一次，下一次同类收益 ×1.12（复利），早期选择会放大到后期。
 *   3. 结局不是一张固定列表，而是 5 个主题 × 6 种代价的组合；另有一条开放式尾声。
 */

export const STAT_KEYS = ['money', 'health', 'love', 'freedom', 'parents', 'regret']

export const STAT_LABELS = {
  money: '钱',
  health: '健康',
  love: '爱',
  freedom: '自由',
  parents: '父母',
  regret: '遗憾'
}

export const DESIRE_LABELS = {
  money: '钱',
  health: '健康',
  love: '被爱',
  freedom: '自由',
  parents: '被期待',
  self: '自己'
}

export const THEME_ORDER = ['money', 'freedom', 'love', 'home', 'self']

export const COST_ORDER = ['health', 'love', 'freedom', 'parents', 'money', 'regret']

const START = { money: 50, health: 80, love: 50, freedom: 50, parents: 50, regret: 10 }

const COST_CANDIDATES = {
  money: ['health', 'love', 'freedom', 'parents', 'regret'],
  freedom: ['money', 'health', 'love', 'parents', 'regret'],
  love: ['money', 'health', 'freedom', 'parents', 'regret'],
  home: ['money', 'health', 'love', 'freedom', 'regret'],
  self: ['money', 'health', 'love', 'freedom', 'parents']
}

const clamp = (value, low, high) => Math.min(high, Math.max(low, Number.isFinite(value) ? value : low))

function hash(text) {
  let value = 2166136261 >>> 0
  for (let index = 0; index < text.length; index += 1) {
    value ^= text.charCodeAt(index)
    value = Math.imul(value, 16777619) >>> 0
  }
  return value
}

function hasFlag(state, flag) {
  return state?.flags?.[flag] === true
}

/**
 * 条件求值器。requires 与章节 variants 共用同一套语法：
 *   flags / notFlags / tags / min / max / desires / any
 * `reason` 只是给玩家看的锁文案，不参与判断。
 */
export function matches(state, when) {
  if (when === undefined || when === null) return true
  if (Array.isArray(when.flags) && !when.flags.every((flag) => hasFlag(state, flag))) return false
  if (Array.isArray(when.notFlags) && when.notFlags.some((flag) => hasFlag(state, flag))) return false
  if (when.tags !== undefined) {
    for (const [key, value] of Object.entries(when.tags)) {
      if (state?.tags?.[key] !== value) return false
    }
  }
  if (when.min !== undefined) {
    for (const [key, value] of Object.entries(when.min)) {
      if ((state?.stats?.[key] ?? 0) < value) return false
    }
  }
  if (when.max !== undefined) {
    for (const [key, value] of Object.entries(when.max)) {
      if ((state?.stats?.[key] ?? 0) > value) return false
    }
  }
  if (when.picks !== undefined) {
    for (const [chapter, option] of Object.entries(when.picks)) {
      if (state?.picks?.[chapter] !== option) return false
    }
  }
  if (when.desires !== undefined) {
    for (const [key, value] of Object.entries(when.desires)) {
      if ((state?.desires?.[key] ?? 0) < value) return false
    }
  }
  if (Array.isArray(when.any) && !when.any.some((sub) => matches(state, sub))) return false
  return true
}

/** 新的一本书。名字只影响复现，不影响规则。 */
export function createSave(name) {
  const seedName = typeof name === 'string' && name.length > 0 ? name : 'xiaoshi'
  return {
    schema: 2,
    seed: hash(seedName),
    name: '小狮',
    age: 18,
    year: 2003,
    chapter: 0,
    depth: 1,
    stats: { ...START },
    tags: { city: '东莞', school: '', job: '', partner: '' },
    desires: { money: 0, health: 0, love: 0, freedom: 0, parents: 0, self: 0 },
    picks: {},
    flags: { ayuan: true },
    premise: '',
    log: [],
    finished: false,
    endingId: ''
  }
}

/** 当前章；越界时返回 null（已经走到结局）。 */
export function chapterOf(state, data) {
  if (state.finished === true) return null
  return data?.chapters?.[state.chapter] ?? null
}

function resolvedText(state, option, key) {
  for (const variant of option?.[`${key}Variants`] ?? []) {
    if (matches(state, variant.when)) return variant[key] ?? ''
  }
  return option?.[key] ?? ''
}

/** 把一章的选项按前置条件分成“可走”和“已锁”。 */
export function optionsFor(state, chapter) {
  return (chapter?.options ?? []).map((option) => {
    const open = option.requires === undefined ? true : matches(state, option.requires)
    return {
      ...option,
      note: resolvedText(state, option, 'note'),
      echo: resolvedText(state, option, 'echo'),
      after: resolvedText(state, option, 'after'),
      locked: !open,
      lockReason: open ? '' : (option.requires?.reason ?? '这条路已经不存在了')
    }
  })
}

/** 章节叙事会随你之前的选择变化；没有命中就回到通用叙事。 */
export function narrationFor(state, chapter) {
  for (const variant of chapter?.variants ?? []) {
    if (matches(state, variant.when)) return variant.narration
  }
  return chapter?.narration ?? ''
}

/**
 * 路径跳转：回答可以把人带到不同的一页。
 * spec 可以是字符串、{goto}、或 [{when, goto}]（第一条命中的生效）。
 */
function pickRoute(state, spec) {
  if (typeof spec === 'string') return spec
  if (Array.isArray(spec)) {
    for (const item of spec) {
      if (item === undefined || item === null) continue
      if (typeof item === 'string') return item
      if (item.when === undefined || matches(state, item.when)) return item.goto
    }
    return null
  }
  if (spec !== null && typeof spec === 'object') {
    if (spec.goto !== undefined) return pickRoute(state, spec.goto)
    if (spec.routes !== undefined) return pickRoute(state, spec.routes)
  }
  return null
}

function nextIndexFor(state, data, chapter, option) {
  if (chapter?.end === true) return -1
  const target = pickRoute(state, option?.goto) ?? pickRoute(state, chapter?.next)
  if (typeof target === 'string') {
    const index = (data?.chapters ?? []).findIndex((item) => item.id === target)
    if (index >= 0) return index
  }
  return state.chapter + 1
}

/** 把一章投影成 UI 和模型都能读的形状。 */
export function sceneOf(state, data) {
  const chapter = chapterOf(state, data)
  if (chapter === null) {
    const ending = endingFor(state, data)
    return {
      finished: true,
      when: `${state.year}年`,
      age: state.age,
      year: state.year,
      chapter: (state.depth ?? 9) - 1,
      total: data?.meta?.pages ?? data?.pages?.length ?? 9,
      ending,
      open: openEnding(state, data, ending),
      stats: { ...state.stats },
      tags: { ...state.tags },
      premise: state.premise ?? ''
    }
  }
  const options = optionsFor(state, chapter)
  return {
    finished: false,
    kind: chapter.kind ?? 'life',
    when: `${chapter.year}年`,
    age: chapter.age,
    year: chapter.year,
    chapter: (chapter.depth ?? state.chapter + 1) - 1,
    total: data?.meta?.pages ?? data?.pages?.length ?? 9,
    id: chapter.id,
    title: chapter.title,
    era: chapter.era ?? null,
    narration: narrationFor(state, chapter),
    options: options.map((option) => ({
      id: option.id,
      label: option.label,
      desire: option.desire,
      desireLabel: DESIRE_LABELS[option.desire] ?? option.desire,
      canon: option.canon === true,
      effects: option.effects ?? {},
      tags: option.tags ?? {},
      note: option.note ?? '',
      echo: option.echo ?? '',
      after: option.after ?? '',
      locked: option.locked,
      lockReason: option.lockReason
    })),
    available: options.filter((option) => !option.locked).length,
    locked: options.filter((option) => option.locked).length,
    stats: { ...state.stats },
    tags: { ...state.tags },
    desires: { ...state.desires },
    flags: { ...state.flags },
    premise: state.premise ?? ''
  }
}

/**
 * 选一个选项：结算数值、记欲望、翻页。
 *
 * 复利只作用于“与这个选项欲望同向的正收益”：
 * 第三次为钱做选择时，钱的收益是 1.24 倍；为“自己”做的选择，
 * 则把遗憾的下降也按复利放大。
 */
export function choose(state, data, optionId) {
  const chapter = chapterOf(state, data)
  if (chapter === null) {
    throw new Error('这一页已经翻完了')
  }
  const option = optionsFor(state, chapter).find((item) => item.id === optionId)
  if (option === undefined) {
    throw new Error(`「${chapter.title}」没有这个选项：${optionId}`)
  }
  if (option.requires !== undefined && !matches(state, option.requires)) {
    throw new Error(option.requires.reason ?? '这条路已经不存在了')
  }

  const before = state.stats
  const count = state.desires?.[option.desire] ?? 0
  const mult = option.desire === undefined ? 1 : 1 + 0.12 * count
  const stats = { ...before }
  const applied = {}
  for (const [key, raw] of Object.entries(option.effects ?? {})) {
    if (!STAT_KEYS.includes(key)) continue
    const value = Number(raw)
    if (!Number.isFinite(value)) continue
    const aligned =
      (key === option.desire && value > 0) ||
      (option.desire === 'self' && key === 'regret' && value < 0)
    const next = Math.round(clamp((stats[key] ?? 0) + (aligned ? value * mult : value), 0, 100))
    applied[key] = next - (stats[key] ?? 0)
    stats[key] = next
  }

  const tags = { ...state.tags, ...(option.tags ?? {}) }
  const flags = { ...state.flags, ...(option.flags ?? {}) }
  const picks = { ...(state.picks ?? {}), [chapter.id]: option.id }
  for (const flag of Array.isArray(option.unset) ? option.unset : []) delete flags[flag]

  const desires = { ...state.desires }
  if (option.desire !== undefined) {
    desires[option.desire] = (desires[option.desire] ?? 0) + 1
  }

  const nextChapter = nextIndexFor(state, data, chapter, option)
  const nextChapterData = data.chapters?.[nextChapter]
  const finished = nextChapterData === undefined
  const partial = {
    ...state, stats, tags, flags, desires, picks,
    chapter: nextChapter,
    depth: nextChapterData?.depth ?? chapter.depth ?? state.depth
  }
  const ending = finished ? endingFor({ ...partial, finished: true }, data) : null
  const next = {
    ...partial,
    year: nextChapterData?.year ?? chapter.year,
    age: nextChapterData?.age ?? chapter.age,
    finished,
    endingId: ending === null ? '' : ending.id,
    log: [
      ...(Array.isArray(state.log) ? state.log : []),
      {
        chapter: chapter.id,
        age: chapter.age,
        title: chapter.title,
        kind: chapter.kind ?? 'life',
        option: option.id,
        label: option.label,
        desire: option.desire,
        mult,
        effects: applied
      }
    ]
  }

  return { state: next, option, effects: applied, mult, after: option.after ?? '', next: sceneOf(next, data) }
}

/** 五个主题的得分；主题不是“你选了哪个欲望”，而是这一生最后被什么定义。 */
export function themeScores(state) {
  const stats = state?.stats ?? START
  const desires = state?.desires ?? {}
  const flags = state?.flags ?? {}
  return {
    money:
      stats.money + 6 * (desires.money ?? 0) +
      (flags.ipo ? 12 : 0) + (flags.bank ? 6 : 0) + (flags.exec ? 6 : 0) +
      (flags.manager ? 4 : 0) + (flags.founder ? 4 : 0),
    freedom:
      stats.freedom + 6 * (desires.freedom ?? 0) +
      (flags.travel ? 6 : 0) + (flags.sold_house ? 6 : 0) + (flags.south ? 8 : 0) +
      (flags.away ? 6 : 0) + (flags.sabbatical ? 6 : 0) + (flags.abroad ? 6 : 0),
    love:
      stats.love + 6 * (desires.love ?? 0) +
      (flags.married ? 6 : 0) + (flags.child ? 4 : 0) + (flags.family ? 8 : 0) +
      (flags.reunited ? 8 : 0) + (flags.stayed ? 4 : 0),
    home:
      stats.parents + 6 * (desires.parents ?? 0) +
      (flags.came_home ? 8 : 0) + (flags.shop_home ? 8 : 0) +
      (flags.school_teacher ? 4 : 0) + (flags.civil ? 4 : 0),
    self:
      25 + 9 * (desires.self ?? 0) +
      Math.max(0, 50 - stats.regret) / 2 +
      (flags.writer_life ? 12 : 0) + (flags.painter_life ? 12 : 0) +
      (flags.craft ? 8 : 0) + (flags.student ? 6 : 0) +
      (flags.restart ? 6 : 0) + (flags.peace ? 8 : 0)
  }
}

export function themeOf(state) {
  const scores = themeScores(state)
  let best = THEME_ORDER[0]
  for (const id of THEME_ORDER) {
    if (scores[id] > scores[best]) best = id
  }
  return { id: best, score: scores[best], scores }
}

/**
 * 代价：主题之外最塌的那一项。低于 47 分、或遗憾高于 53 分，
 * 才会被算作“这一生的代价”；否则是“圆满”。
 */
export function costOf(state, theme) {
  const stats = state?.stats ?? START
  const candidates = COST_CANDIDATES[theme] ?? COST_CANDIDATES.money
  // 遗憾过重时，它就是这一生的主代价——哪怕别的数字也不好看。
  if (theme !== 'self' && candidates.includes('regret') && stats.regret >= 55) {
    return { id: 'regret', deficit: stats.regret - 53, value: stats.regret }
  }
  let best = 'none'
  let deficit = 0
  for (const key of candidates) {
    const value = key === 'regret' ? stats.regret - 53 : 47 - stats[key]
    if (value > deficit) {
      deficit = value
      best = key
    }
  }
  return { id: best, deficit, value: best === 'none' ? 0 : stats[best] }
}

export function endingCell(state) {
  const theme = themeOf(state)
  const cost = costOf(state, theme.id)
  return { theme: theme.id, cost: cost.id, id: `${theme.id}-${cost.id}`, themeScore: theme.score, costDeficit: cost.deficit }
}

/**
 * 结局：三十种组合，全部可达。没有“没有结局”的状态。
 */
export function endingFor(state, data) {
  const endings = data?.endings ?? []
  const special = endings.find((ending) => ending.kind === 'special' && matches(state, ending.when))
  if (special !== undefined) {
    return { ...special, theme: null, cost: null, cell: special.id }
  }
  const cell = endingCell(state)
  const found = endings.find((ending) => ending.id === cell.id)
  const ending = found ?? endings.find((item) => item.theme === cell.theme) ?? endings[0] ?? {
    id: 'self-none', theme: 'self', cost: 'none', title: '自己的答案', subtitle: '', text: '', comment: '', hint: ''
  }
  return {
    ...ending,
    theme: ending.theme ?? cell.theme,
    cost: ending.cost ?? cell.cost,
    cell: cell.id
  }
}

/**
 * 开放式尾声：不新增结局 id，而是把这一生的具体碎片拼出来。
 * 同一份结局，城市、工作、身边的人、身体、父母、遗憾不同，文字就不同。
 */
export function openEnding(state, data, ending = endingFor(state, data)) {
  const stats = state?.stats ?? START
  const tags = state?.tags ?? {}
  const fragments = [
    `${tags.city || '一座没有名字的城'}，${tags.job || '没有固定的工作'}`,
    tags.partner ? `身边是${tags.partner}` : '身边没有人，也没有人等门',
    stats.health >= 70 ? '身体还算争气' : stats.health >= 45 ? '身体不好不坏' : '身体先亮了红灯',
    stats.parents >= 70 ? '父母那边，你几乎没有缺席' : stats.parents >= 45 ? '父母那边，你尽力了' : '父母那边，你欠着一些没回去的周末',
    stats.regret >= 55 ? '你还是常常想起另一条路' : stats.regret >= 30 ? '偶尔你会想，如果当时……' : '你很少再想“如果”'
  ]
  return {
    fragments,
    line: fragments.join('；') + '。',
    premise: state?.premise ?? '',
    title: ending?.title ?? '',
    theme: ending?.theme ?? '',
    cost: ending?.cost ?? ''
  }
}

/** 给模型的紧凑 digest；不含任何叙述文本以外的世界数据。 */
export function buildDigest(state, data) {
  const chapter = chapterOf(state, data)
  const canon = data?.canon ?? {}
  const base = {
    title: data?.title ?? '小狮日记 · 人生之书',
    memory: data?.memory ?? null,
    when: chapter === null ? `${state.year}年` : `${chapter.year}年`,
    age: chapter?.age ?? state.age,
    chapter: (state.depth ?? 9) - 1,
    total: data?.meta?.pages ?? data?.pages?.length ?? 9,
    stats: { ...state.stats },
    tags: { ...state.tags },
    desires: { ...state.desires },
    flags: { ...state.flags },
    premise: state.premise ?? '',
    people: (canon.people ?? []).map((person) => ({ name: person.name, role: person.role }))
  }
  if (chapter === null) {
    return { ...base, finished: true, ending: endingFor(state, data), open: openEnding(state, data) }
  }
  const options = optionsFor(state, chapter)
  return {
    ...base,
    finished: false,
    kind: chapter.kind ?? 'life',
    chapterId: chapter.id,
    sceneTitle: chapter.title,
    era: chapter.era ?? null,
    narration: narrationFor(state, chapter),
    options: options.map((option) => ({
      id: option.id,
      label: option.label,
      desire: DESIRE_LABELS[option.desire] ?? option.desire,
      canon: option.canon === true,
      effects: option.effects ?? {},
      note: option.note ?? '',
      locked: option.locked,
      lockReason: option.lockReason
    }))
  }
}

/** 给模型的人类可读摘要。 */
export function renderDigest(digest) {
  const lines = [
    `${digest.when} · ${digest.age}岁 · ${digest.title}`,
    ...(digest.memory?.birth ? [`出生：${digest.memory.birth}`] : []),
    `钱 ${digest.stats.money}　健康 ${digest.stats.health}　爱 ${digest.stats.love}　` +
      `自由 ${digest.stats.freedom}　父母 ${digest.stats.parents}　遗憾 ${digest.stats.regret}`,
    `城市 ${digest.tags.city}　学校 ${digest.tags.school || '—'}　工作 ${digest.tags.job || '—'}　` +
      `伴侣 ${digest.tags.partner || '—'}`,
    `欲望账本：${Object.entries(digest.desires).filter(([, count]) => count > 0).map(([key, count]) => `${DESIRE_LABELS[key] ?? key}×${count}`).join('、') || '无'}`
  ]
  if (digest.premise) lines.push(`你带着的那个如果：${digest.premise}`)
  if (digest.era?.hot?.length > 0) lines.push(`${digest.era.source ?? '那年'}：${digest.era.hot.join(' · ')}`)
  if (digest.finished === true) {
    lines.push(`结局：${digest.ending.title}——${digest.ending.subtitle}`)
    lines.push(`开放式尾声：${digest.open?.line ?? ''}`)
    return lines.join('\n')
  }
  lines.push('', `【${digest.sceneTitle}】`, digest.narration)
  for (const option of digest.options ?? []) {
    if (option.locked) {
      lines.push(`- （锁）${option.label}：${option.lockReason}`)
      continue
    }
    lines.push(
      `- ${option.label}（${option.desire}${option.canon ? ' · 当年' : ' · 如果'}）` +
      `${option.note.length > 0 ? `：${option.note}` : ''}`
    )
  }
  return lines.join('\n')
}

/** 写进 `.life/life.json` 的投影；卡面只读它。 */
export function projection(state, data) {
  const scene = sceneOf(state, data)
  return {
    schema: 2,
    present: true,
    when: scene.when,
    age: scene.age,
    chapter: scene.chapter,
    total: data?.chapters?.length ?? 0,
    kind: scene.finished ? 'ending' : scene.kind,
    title: scene.finished ? '人生之书' : scene.title,
    narration: scene.finished ? '' : scene.narration,
    era: scene.finished ? null : scene.era,
    premise: state.premise ?? '',
    stats: state.stats,
    tags: state.tags,
    desires: state.desires,
    picks: state.picks,
    flags: state.flags,
    finished: state.finished,
    ending: scene.finished ? scene.ending : null,
    open: scene.finished ? scene.open : null,
    options: scene.finished ? [] : scene.options,
    generatedAt: new Date().toISOString()
  }
}
